#pragma once
#include <furi.h>

#include "command_observed.h"

/*
 * Command catalogue.
 *
 * Two different things live here, and they must not be mixed:
 *
 *  1. WHAT WAS MEASURED — kObservedCommands[] in command_observed.h is
 *     generated by tools/gen_command_observed.py from the 5 btsnoop captures.
 *     It states, per command id, how many frames the central sent, how many the
 *     watch answered, on which handles, and a real sample payload.
 *
 *  2. WHAT IS SAFE TO DO — the table below is a POLICY, written by hand. It is
 *     not a measurement. A command marked DANGEROUS can still be perfectly
 *     valid; it is just not allowed to run without the user confirming.
 */

typedef enum {
    CMD_SAFETY_SAFE = 0, /* read-only request, no watch state change */
    CMD_SAFETY_CAUTION, /* may change watch state */
    CMD_SAFETY_DANGEROUS, /* modifies settings, alarms or time */
    CMD_SAFETY_BLOCKED, /* never auto-execute */
} CmdSafety;

typedef struct {
    uint8_t id;
    const char* name;
    CmdSafety safety;
    const char* description;
} CmdEntry;

/* Policy lookup. Returns NULL if the command is not classified. */
const CmdEntry* cmd_lookup(uint8_t id);

/* Policy table size. */
uint32_t cmd_count(void);

/* Measured data for a command id, or NULL if it never appeared in a capture. */
const CasioObservedCommand* cmd_observed(uint8_t id);

/* Number of distinct command ids seen on the wire. */
uint32_t cmd_observed_count(void);

const char* cmd_safety_name(CmdSafety safety);
